 AND format_type(a.atttypid,a.atttypmod)=('text') AND a.attnotnull=(false)
 AND a.attidentity='' AND a.attgenerated=''
 AND pg_get_expr(d.adbin,d.adrelid) IS NOT DISTINCT FROM (NULL)))
 AND (SELECT EXISTS(SELECT 1 FROM pg_attribute a
 LEFT JOIN pg_attrdef d ON d.adrelid=a.attrelid AND d.adnum=a.attnum
 WHERE a.attrelid=to_regclass('public.'||('byod_import_jobs')) AND a.attname=('created_at') AND NOT a.attisdropped
 AND format_type(a.atttypid,a.atttypmod)=('timestamp with time zone') AND a.attnotnull=(false)
 AND a.attidentity='' AND a.attgenerated=''
 AND pg_get_expr(d.adbin,d.adrelid) IS NOT DISTINCT FROM ('now()')))
 AND (SELECT EXISTS(SELECT 1 FROM pg_attribute a
 LEFT JOIN pg_attrdef d ON d.adrelid=a.attrelid AND d.adnum=a.attnum
 WHERE a.attrelid=to_regclass('public.'||('byod_import_jobs')) AND a.attname=('updated_at') AND NOT a.attisdropped
 AND format_type(a.atttypid,a.atttypmod)=('timestamp with time zone') AND a.attnotnull=(false)
 AND a.attidentity='' AND a.attgenerated=''
 AND pg_get_expr(d.adbin,d.adrelid) IS NOT DISTINCT FROM ('now()')))
 AND (SELECT EXISTS(SELECT 1 FROM pg_constraint c
 WHERE c.conrelid=to_regclass('public.'||('byod_import_jobs'))
 AND c.convalidated AND NOT c.condeferrable AND NOT c.condeferred
 AND pg_get_constraintdef(c.oid)=('PRIMARY KEY (id)')
 AND (c.contype NOT IN ('p','u') OR EXISTS (
   SELECT 1 FROM pg_index i WHERE i.indexrelid=c.conindid
